{
  "summary": "2019 Nissan Kicks forward collision avoidance warnings; intermittent P0101/P0102 with check engine, traction and collision warning lights; drivability affected and engine restart required.",
  "group": "adas",
  "symptoms": [
    "occasional fault codes P0101 and P0102 when the check engine light comes on",
    "traction warning light illuminates",
    "forward collision warning light illuminates",
    "driving behavior is affected",
    "engine must be shut off for a few minutes and restarted",
    "mass air flow sensor replacement did not resolve the issue"
  ],
  "conditions": [
    "intermittent"
  ],
  "fault_codes": [
    "P0101",
    "P0102"
  ],
  "safety_relevant": false,
  "missing_info": [
    "mileage",
    "date"
  ],
  "clues": [
    {
      "kind": "component_group",
      "quote": "FORWARD COLLISION AVOIDANCE: WARNINGS"
    },
    {
      "kind": "fault_code",
      "quote": "Code P0101 and P0102"
    },
    {
      "kind": "condition",
      "quote": "ocassionally"
    },
    {
      "kind": "symptom",
      "quote": "when the check Engine light comes on"
    },
    {
      "kind": "symptom",
      "quote": "The Traction Light and Head Collision warning lights show as well"
    },
    {
      "kind": "symptom",
      "quote": "These affect how the car drives"
    },
    {
      "kind": "symptom",
      "quote": "I have to stop and shut of the engine for a couple of minutes and then restart the engine"
    },
    {
      "kind": "other",
      "quote": "Changing the Mass Air flor sensor does not seem to have helped anything"
    },
    {
      "kind": "other",
      "quote": "several people who own similar cars are having the same issue"
    }
  ]
}

